CREATE DATABASE IF NOT EXISTS supermarket_pos;
USE supermarket_pos;

-- Clean existing tables if present for fresh data setup
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS pos_sale_items;
DROP TABLE IF EXISTS pos_sales;
SET FOREIGN_KEY_CHECKS = 1;

-- 1. Sales transaction table
CREATE TABLE IF NOT EXISTS pos_sales (
    sale_id INT PRIMARY KEY,
    sale_datetime DATETIME NOT NULL,
    customer_id INT NOT NULL,
    branch_id INT NOT NULL,
    payment_method VARCHAR(30),
    status VARCHAR(20) DEFAULT 'COMPLETED'
);

-- 2. Sales item details table
CREATE TABLE IF NOT EXISTS pos_sale_items (
    sale_item_id INT PRIMARY KEY,
    sale_id INT NOT NULL,
    product_id INT NOT NULL,
    quantity INT NOT NULL,
    unit_price DECIMAL(10,2) NOT NULL,
    discount_amount DECIMAL(10,2) DEFAULT 0,

    CONSTRAINT fk_pos_sale
        FOREIGN KEY (sale_id)
        REFERENCES pos_sales(sale_id),

    CONSTRAINT chk_quantity
        CHECK (quantity > 0),

    CONSTRAINT chk_unit_price
        CHECK (unit_price >= 0),

    CONSTRAINT chk_discount
        CHECK (discount_amount >= 0)
);

-- 3. Sales transactions (120 orders across 2026)

-- 4. Sale item details (415 items across products 1001-1028)

-- 5. Verification queries
SELECT COUNT(*) AS total_sales FROM pos_sales;
SELECT COUNT(*) AS total_sale_items FROM pos_sale_items;
SELECT payment_method, COUNT(*) AS txn_count FROM pos_sales GROUP BY payment_method;
SELECT status, COUNT(*) AS txn_count FROM pos_sales GROUP BY status;
